lifeKinds.tunnel='Парник на грядке';lifeKinds.greenhouse='Теплица';
function upgradePrice(u,p){const area=Number(p?.size||3);return Math.round(500+(u.price-500)*Math.max(1,u.basis==='perimeter'?2*((Number(p?.width_m)||1)+(Number(p?.length_m)||area))/8:area/3))}
function upgradeBlocked(u,p){if(!p)return '';const ids=['wood','concrete'].includes(u.id)?['wood','concrete']:['cover','tunnel','greenhouse'].includes(u.id)?['cover','tunnel','greenhouse']:[u.id];if((lifeData?.requests||[]).some(r=>r.plot_id===p.id&&ids.includes(r.catalog_id)&&r.status!=='cancelled'&&!(r.status==='done'&&(lifeData?.equipment||[]).some(e=>e.request_id===r.id&&e.condition==='retired'))))return 'Уже установлено или заказано';if(['wood','concrete','greenhouse'].includes(u.id)&&!['unchecked','empty','ready','finished'].includes(p.growing_state))return 'После сбора урожая';return ''}
function upgradeCards(plot){return `<section class="panel"><h2>Улучшения из маркета</h2><p>Предварительные демо-цены с монтажом. Бортики считаются по периметру, по подтверждённым размерам; до измерения используем предварительную ширину 1 м. Ферма подтвердит совместимость, стоимость и срок до выполнения.</p><div class="room-actions">${bedUpgrades.map(u=>roomTile(u.icon,u.name,u.description,`orderBedUpgrade('${u.id}',${plot?.id||'null'})`,upgradeBlocked(u,plot)||`${plot?'':'От '}${upgradePrice(u,plot)} демо-₽`,!!upgradeBlocked(u,plot))).join('')}</div></section>`}
function orderBedUpgrade(id,plot){if(!account)return profile();if(!myPlots().length){toast('Сначала арендуйте грядку');return}const u=bedUpgrades.find(u=>u.id===id);if(!u)return;const requestKey=crypto.randomUUID();const chosen=myPlots().find(p=>p.id===plot)||myPlots()[0];formAsync(u.name,`<label>Грядка<select name="plot" onchange="updateUpgradeQuote('${id}',this.value)">${myPlots().map(p=>`<option value="${p.id}" ${p.id===chosen.id?'selected':''}>${esc(p.name)} · ${p.size} м²</option>`).join('')}</select></label><h3 id="upgrade-quote">${upgradePrice(u,chosen)} демо-₽ · предварительно</h3><p>${u.description}</p><label>Пожелания<textarea name="notes" maxlength="400"></textarea></label><p>Создаётся одна заявка на согласование. Деньги сейчас не списываются. Сотрудник уточнит смету и время работ.</p><button class="btn">Отправить заявку на установку</button>`,async f=>{const p=myPlots().find(p=>p.id===Number(f.get('plot')));if(!p)throw Error('Выберите свою грядку');await api('life-request',{plot:p.id,kind:u.kind,catalog_id:u.id,key:requestKey,details:`[Улучшение: ${u.id}] ${u.name}. Площадь ${p.size} м². Предварительная демо-смета ${upgradePrice(u,p)} ₽, материалы и монтаж. Требует согласования. ${f.get('notes')||''}`});await loadLife();openFarmBed(p.id,'activity');toast('Заявка отправлена и видна в ходе работ')})}
function updateUpgradeQuote(id,plot){const u=bedUpgrades.find(x=>x.id===id),p=myPlots().find(x=>x.id===Number(plot));document.getElementById('upgrade-quote').textContent=upgradePrice(u,p)+' демо-₽ · предварительно'}
const marketBeforeUpgrades=demoMarketPage;demoMarketPage=function(){return upgradeCards()+marketBeforeUpgrades()};
const renderBeforeUpgrades=render;render=function(){renderBeforeUpgrades();const p=currentRoomPlot();if(p&&plotRoomTab==='build')document.querySelector('[role=tabpanel]')?.insertAdjacentHTML('afterbegin',upgradeCards(p));if(p&&['activity','build'].includes(plotRoomTab)){const requests=(lifeData?.requests||[]).filter(r=>r.plot_id===p.id);if(requests.length)document.querySelector('[role=tabpanel]')?.insertAdjacentHTML('beforeend',`<section class="panel"><h2>Установка и улучшения</h2>${requests.map(r=>`<article class="event"><b>${esc(lifeKinds[r.kind]||'Улучшение')}</b><p>${esc(r.details)}</p><span class="pill">${esc(lifeStatus[r.status]||r.status)}</span><p>${esc(r.report||'Ожидает согласования фермы')}</p>${upgradePaymentCard(r)}${account.role==='admin'?`<button class="btn light" onclick="reviewLifeRequest('${r.id}')">Обновить статус</button>`:''}</article>`).join('')}</section>`)}};
addEventListener('hashchange',()=>{if(account&&(currentRoomPlot()||location.hash==='#market'))loadLife()});if(account)loadLife();render();

function upgradePaymentCard(r){if(!r.catalog_id)return '';return `<p>${r.quote?.confirmed?'Согласованная':'Предварительная'} смета: <b>${money(r.quote?.amount_kopecks||0)}</b>${r.quote?.finish_by?' · до '+fmt(r.quote.finish_by):''}</p>${r.paid_at?'<span class="pill">Демо-смета оплачена</span>':r.status==='reviewed'&&r.quote?.confirmed&&r.user_id===account.id?`<button class="btn" onclick="payUpgrade('${r.id}')">Согласовать и оплатить демобалансом</button>`:''}`}
function payUpgrade(id){const r=lifeData.requests.find(x=>x.id===id);if(!r)return;formAsync('🛠️ Улучшаем грядку',`<h3>${esc(lifeKinds[r.kind])}</h3><p>${esc(r.report)}</p><h3>${money(r.quote.amount_kopecks)}</h3><p>Материалы: ${money(r.quote.materials_kopecks||0)} · работа: ${money(r.quote.labor_kopecks||0)} · прочее: ${money(r.quote.overhead_kopecks||0)}.</p><p>До ${fmt(r.quote.finish_by)}. Оплата тестовыми средствами. Фактические работы отдельно подтверждает ферма.</p><button class="btn">Оплатить демобалансом</button>`,async()=>{await api('life-upgrade-pay',{id,amount:r.quote.amount_kopecks,version:r.quote.version});walletData=null;await loadLife();toast('Смета оплачена демобалансом')})}
const reviewGeneralRequest=reviewLifeRequest;
reviewLifeRequest=function(id){const r=lifeData.requests.find(x=>x.id===id);if(!r?.catalog_id)return reviewGeneralRequest(id);formAsync('Смета и установка',`<label>Статус<select name="status"><option value="reviewed">Согласовать смету</option><option value="done">Демо-установка выполнена</option><option value="cancelled">Отменить и вернуть оплату</option></select></label><label>Итоговая цена, демо-₽<input type="number" name="price" min="1" step="0.01" value="${(r.quote?.amount_kopecks||0)/100}"></label><label>Материалы, ₽<input name="materials" type="number" min="0" step="0.01" value="${(r.quote?.materials_kopecks||0)/100}"></label><label>Работа, ₽<input name="labor" type="number" min="0" step="0.01" value="${(r.quote?.labor_kopecks||0)/100}"></label><label>Прочее, ₽<input name="overhead" type="number" min="0" step="0.01" value="${(r.quote?.overhead_kopecks||0)/100}"></label><label>Установить до<input type="datetime-local" name="finish"></label><label>Состав, совместимость, условия или отчёт<textarea name="report" required minlength="10"></textarea></label><p>Смета включает материалы, монтаж и отчёт. После оплаты изменение цены запрещено.</p><button class="btn">Сохранить</button>`,async f=>{const value=Object.fromEntries(f);await lifeAction('request-review',{id,status:value.status,report:value.report,amount:Math.round(Number(value.price)*100),materials:Math.round(Number(value.materials)*100),labor:Math.round(Number(value.labor)*100),overhead:Math.round(Number(value.overhead)*100),finish:value.finish?new Date(value.finish).toISOString():null})})};
